import{_ as e,o as d,c,a5 as p}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"Jdk、jre和jvm","description":"","frontmatter":{"title":"Jdk、jre和jvm","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/00-开发环境/Jdk、jre和jvm.md","filePath":"posts/java快速入门/第一部分：语言基础/00-开发环境/Jdk、jre和jvm.md"}'),a={name:"posts/java快速入门/第一部分：语言基础/00-开发环境/Jdk、jre和jvm.md"};function t(J,o,n,r,s,v){return d(),c("div",null,[...o[0]||(o[0]=[p('<div><p><code>Java</code><strong>虚拟机——</strong></p><ul><li>JVM</li><li>JVM</li></ul><p>（<code>Java Virtual Machine</code> ）：<code>Java</code>虚拟机，简称<code>JVM</code>，是运行所有<code>Java</code>程序的假想计算机，是<code>Java</code>程序的 运行环境，是<code>Java</code> 最具吸引力的特性之一。我们编写的<code>Java</code>代码，都运行在 <code>JVM</code> 之上。</p><p><strong>跨平台</strong>：任何软件的运行，都必须要运行在操作系统之上，而我们用<code>Java</code>编写的软件可以运行在任何的操作系 统上，这个特性称为<code>Java</code><strong>语言的跨平台特性</strong>。该特性是由<code>JVM</code>实现的，我们编写的程序运行在<code>JVM</code>上，而<code>JVM</code> 运行在操作系统上。</p><p>如图所示，<code>Java</code>的虚拟机本身不具备跨平台功能的，每个操作系统下都有不同版本的虚拟机。</p><p><code>JRE</code> <strong>和</strong></p><ul><li>JDK</li><li>JRE (Java Runtime Environment)</li></ul><p>：是<code>Java</code>程序的运行时环境，包含 <code>JVM</code> 和运行时所需要的 核心类库 。</p><p><code>JDK (Java Development Kit)</code></p><p>：是<code>Java</code>程序开发工具包，包含 <code>JRE</code> 和开发人员使用的工具。</p><p><code>JDK</code></p><p>是整个 <code>JAVA</code> 的核心，包括了 <code>Java</code> 运行环 境（<code>Java Runtime Environment</code>），一堆 <code>Java</code> 工具（<code>javac/java/jdb</code> 等）和 <code>Java</code> 基础的类库（即 <code>Java API</code> 包括 <code>rt.jar</code>）。 它不提供具体的开发软件，它提供的是无论你用何种开发软件写 <code>Java</code> 程序都必须用到的类库和 <code>Java</code> 语言规范。</p><p>我们想要运行一个已有的<code>Java</code>程序，那么只需安装 <code>JRE</code> 即可。 我们想要开发一个全新的<code>Java</code>程序，那么必须安装 <code>JDK</code> 。</p><p>小贴士： 三者关系： <code>JDK \\&gt; JRE \\&gt; JVM</code></p><p><code>2.3 JDK9</code><strong>安装之后</strong><code>JAVA_HOME</code><strong>环境变量的配置</strong><strong>配置环境变量作用</strong> 开发<code>Java</code>程序，需要使用<code>JDK</code>中提供的工具，工具在<code>JDK9</code>安装目录的 <code>bin</code> 目录下。</p><p>在<code>DOS</code>命令行下使用这些工具，就要先进入到<code>JDK</code>的<code>bin</code>目录下，这个过程就会非常的麻烦。</p><p>不进入<code>JDK</code>的 <code>bin</code> 目录，这些工具就不能使用，会报错。</p><p>为了开发方便，我们想<strong>在任意的目录下都可以使用</strong><code>JDK</code><strong>的开发工具</strong>，则必须要配置环境变量，配置环境变量的意义 在于告诉操作系统，我们使用的<code>JDK</code>开发工具在哪个目录下。</p><p><strong>配置环境变量步骤</strong></p><p><code>Windows 7,8</code></p><p><strong>版本</strong></p><p><code>1.</code></p><p>计算机鼠标右键<code>,</code>选择 属性</p><p><code>2.</code></p><p>选择 高级系统设置</p><p><code>3.</code></p><p>高级 选项卡，点击 环境变量</p><p><code>4.</code></p><p>点击 新建 ，创建新的环境变量</p><p><code>5.</code></p><p>变量名输入 <code>JAVA_HOME</code> ，变量值输入<code>JDK9</code>的安装目录</p><ul><li>c:\\Java9\\jdk-9.0.1</li><li><ol start="6"><li></li></ol></li></ul><p>选中 <code>Path</code> 环境变量， 双击 或者 点击编辑</p><p><code>7.</code></p><p>在变量值的最前面，键入 <code>%JAVA_HOME%\\bin;</code> 分号必须要写，必须是英文格式。</p><p><code>8.</code></p><p>环境变量配置完成，重新开启<code>DOS</code>命令行，在任意目录下输入 <code>javac</code> 命令，运行成功。</p><p><code>Windows 10</code> <strong>版本</strong></p><p><code>1.</code></p><p>文件资源管理器 <code>--\\&gt;</code> 此电脑鼠标右键 <code>--\\&gt;</code> 选择 属性</p><p><code>2.</code></p><p>选择 高级系统设置 <code>--\\&gt;</code> 选择 环境变量</p><p><code>3.</code></p><p>点击下方系统变量的 新建 ，创建新的环境变量，变量名输入 <code>JAVA_HOME</code> ，变量值输入<code>JDK9</code>的安装目录</p><ul><li>D:\\02_DevelopTools\\Java\\jdk-9.0.1</li><li><ol start="4"><li></li></ol></li></ul><p>选中 <code>Path</code> 环境变量， 双击 或者 点击编辑</p><p><code>5.</code></p><p>点击 新建 ，键入 <code>%JAVA_HOME%\\bin</code> ，必须是英文格式。选中该行，上移到最上方，点击确定。</p><p><code>6.</code></p><p>环境变量配置完成，重新开启<code>DOS</code>命令行，在任意目录下输入 <code>javac</code> 命令。</p></div>',1)])])}const g=e(a,[["render",t]]);export{l as __pageData,g as default};
